-- Name: NPS Variant wise Correct - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp AS ( SELECT rb_user_id, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant FROM user_interaction.search_route_details s WHERE s.__time >= TIMESTAMP '2026-07-13 18:30:00' AND s.__time < TIMESTAMP '2026-07-27 18:30:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND tp_channel = 'INVALID' AND country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), doj) = 0 GROUP BY 1,2 ), NPS AS ( SELECT DISTINCT DATE(DATE_ADD('MINUTE', 330, a.received_on)) AS ReceivedOn, a.survey_id AS SurveyId, a.redbus_userid AS rb_user_id, -- CASE WHEN a.question_option_id = 17 THEN 0 ELSE a.question_option_id END AS NPS_Score, CASE WHEN a.question_option_id IN (17, 1, 2, 3, 4, 5, 6, 0) THEN 'Detractors' WHEN a.question_option_id IN (7, 8) THEN 'Neutrals' WHEN a.question_option_id IN (9, 10) THEN 'Promoters' END AS NPS_Type, CASE WHEN a.survey_id = 9 THEN 'Booking' WHEN a.survey_id = 1 THEN 'Travel' ELSE 'Cancellation' END AS Survey_Type, -- a.email, -- a.mobile_number AS mobilenumber, a.order_number AS ordernumber, a.business_unit AS businessunit, a.feedback, a.channel, n.operator_id AS bo_id, n.service_provider_name AS bo_name, -- c.survey_info, n.selected_language, n.source_location_id, n.destination_location_id, n.source_location, n.destination_location, CASE WHEN bo.is_rtc = 'RTC' THEN 'RTC' ELSE 'Pvt' END AS RTC, n.user_type, n.route_id, -- CASE WHEN (n.source_location_id, n.destination_location_id) IN (SELECT src_id, dest_id FROM "lis"."short_route_sds") THEN 'Short Route' ELSE 'Long Route' END AS route_cohort n.date_of_issue AS bookingtime, n.date_of_journey, n.boarding_time, CASE WHEN n.is_ac = TRUE THEN 'AC' ELSE 'non-AC' END AS is_ac -- COALESCE(CAST(bc.time_of_event AS VARCHAR), 'Not Cancelled') AS cancellationtime, -- COALESCE(bc.cancellation_type, 'Not Cancelled') AS cancellationtype FROM "ugc"."nps_survey_response" AS a -- LEFT JOIN "ugc"."nps_survey_info_response" AS c -- ON a.key = c.key LEFT JOIN "transaction"."bus_ticket_events" AS n ON a.order_number = n.tin -- LEFT JOIN "transaction"."bus_cancellation_events" AS bc -- ON a.order_number = bc.tin JOIN lis.bo_mappings bo ON bo.vendor_id = n.operator_id WHERE a.received_on >= TIMESTAMP '2026-07-13 18:30:00' AND a.received_on < TIMESTAMP '2026-07-27 18:30:00' AND n.time_of_event >= TIMESTAMP '2026-07-13 18:30:00' AND n.time_of_event < TIMESTAMP '2026-07-27 18:30:00' AND a.question_option_id <> -1 AND a.business_unit = 1 AND a.country_code = 1 AND n.country_code = 'IND' -- AND bc.country_code = 'IND' -- ORDER BY ReceivedOn ) SELECT -- n.ReceivedOn, -- '16 to 30 June 2026' AS time_period, -- '01 to 13 July 2026' AS time_period, '14 to 27 July 2026' AS time_period, n.channel, n.Survey_Type, s.exp_variant, n.is_ac, -- n.source_location_id, n.destination_location_id, n.source_location, n.destination_location, COUNT(DISTINCT CASE WHEN n.NPS_Type = 'Promoters' THEN (n.ReceivedOn, n.rb_user_id) END) AS Promoters_nps_received, COUNT(DISTINCT CASE WHEN n.NPS_Type = 'Neutrals' THEN (n.ReceivedOn, n.rb_user_id) END) AS Neutrals_nps_received, COUNT(DISTINCT CASE WHEN n.NPS_Type = 'Detractors' THEN (n.ReceivedOn, n.rb_user_id) END) AS Detractors_nps_received, COUNT(DISTINCT (n.ReceivedOn, n.rb_user_id)) Overall_nps_received FROM NPS n LEFT JOIN srp s ON s.rb_user_id = n.rb_user_id WHERE s.exp_variant IN ('V0', 'V1', 'V2') AND RTC = 'RTC' GROUP BY 1, 2, 3, 4, 5 -- , 6, 7, 8, 9 ORDER BY 1, 2, 3, 4
